-- Sliver row35 is the independent TEXT_OVER(12,101539) departure callback.
-- Retain its native waypoint-start admission and failed-start repeat flag.
-- Row34 sends Minerva3/3 on that same timer; it must not call row35 as LINK.
SET @sliver_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=GREATEST(@@SESSION.group_concat_max_len,1048576);
START TRANSACTION;
SET @sliver_smart_scripts=(SELECT SHA2(COALESCE(GROUP_CONCAT(CONCAT_WS('|',COALESCE(CAST(`entryorguid` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`source_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`id` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`link` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`Difficulties` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_phase_mask` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_chance` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_flags` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`event_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param5` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`action_param6` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_type` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param1` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param2` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param3` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_param4` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_x` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_y` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_z` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`target_o` AS CHAR CHARACTER SET utf8mb4),'NULL'),COALESCE(CAST(`comment` AS CHAR CHARACTER SET utf8mb4),'NULL')) ORDER BY `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_x`,`target_y`,`target_z`,`target_o`,`comment` SEPARATOR '\n'),''),256) FROM smart_scripts WHERE entryorguid IN(101539,102561,10153900) AND source_type IN(0,9));
